import json,struct,sys
for k in range(5):
  b=open(f'p{k}.glb','rb').read(); jl=struct.unpack_from('<I',b,12)[0]; j=json.loads(b[20:20+jl])
  bv=j['bufferViews']; acc=j['accessors']
  img=sum(bv[i['bufferView']]['byteLength'] for i in j['images'])
  an={}
  for a in j['animations']:
    s=set()
    for sm in a['samplers']: s.add(sm['input']); s.add(sm['output'])
    an[a['name']]=sum(bv[acc[x]['bufferView']]['byteLength'] for x in s)
  ch={}
  for a in j['animations']:
    for c in a['channels']: ch[c['target']['path']]=ch.get(c['target']['path'],0)+1
  print(k,len(b),'img',img,[(i.get('mimeType'),bv[i['bufferView']]['byteLength']) for i in j['images']],'anim',an,ch)
"

