def pick_loop(sc, src, f0, f1, lo, hi, bones):
    """Chọn khung cuối e trong [lo, hi] sao cho tư thế e gần tư thế f0 nhất (vòng lặp khớp)."""
    s0 = pose_sample(sc, src, f0, bones); best = (1e9, f1)
    for e in range(max(lo, f0 + 2), min(hi, f1) + 1):
        d = pose_dist(s0, pose_sample(sc, src, e, bones))
        if d < best[0]: best = (d, e)
    return best[1], best[0]

