// Nạp p0..p4.glb bằng GLTFLoader của three trong Node, kiểm hướng mặt và xương
import { readFileSync } from 'node:fs';
const R = 'file:///D:/2026%20-%20Tuan/danang-vite/node_modules/three/';
const THREE = await import(R + 'build/three.module.js');
const { GLTFLoader } = await import(R + 'examples/jsm/loaders/GLTFLoader.js');
const origErr = console.error; console.error = () => {}; console.warn = () => {};
for (let k = 0; k < 5; k++) {
  const b = readFileSync(`D:/2026 - Tuan/danang-vite/public/people/p${k}.glb`);
  const ab = b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength);
  const g = await new Promise((res, rej) => new GLTFLoader().parse(ab, '', res, rej));
  g.scene.updateMatrixWorld(true);
  const v = n => g.scene.getObjectByName(n).getWorldPosition(new THREE.Vector3());
  const toe = v('Bip01_L_Toe0'), foot = v('Bip01_L_Foot'), head = v('Bip01_Head'), eye = v('Bip01_LEye');
  let skinned = 0; g.scene.traverse(o => { if (o.isSkinnedMesh) skinned++; });
  const box = new THREE.Box3().setFromObject(g.scene);
  // chạy mixer: chân trái so với hông thay đổi khi sprint
  const mixer = new THREE.AnimationMixer(g.scene); const clip = g.animations.find(a => a.name === 'sprint');
  mixer.clipAction(clip).play(); const xs = [];
  for (let i = 0; i < 20; i++) { mixer.update(clip.duration / 20); g.scene.updateMatrixWorld(true); xs.push(v('Bip01_L_Foot').x - v('Bip01_Pelvis').x); }
  console.log(`p${k}: anims ${g.animations.map(a => `${a.name}:${a.duration.toFixed(2)}`).join(' ')} | skinned ${skinned} | toe-foot (${(toe.x - foot.x).toFixed(3)}, ${(toe.y - foot.y).toFixed(3)}, ${(toe.z - foot.z).toFixed(3)}) | eye-head x ${(eye.x - head.x).toFixed(3)} | box y ${box.min.y.toFixed(3)}..${box.max.y.toFixed(3)} | height ${g.scene.userData.height} | foot swing ${(Math.max(...xs) - Math.min(...xs)).toFixed(2)} m`);
}
console.error = origErr;

